//! 🏗️ Source birth keeps real input, backing and parent owners in separately paid resident slots.
use super::*;
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedWorkOutcome,RetainedCloneStep};

/// 🧳️ Owns the same assembled Source roots and successful sealed backing until publication or return.
pub struct OriginalCallerSourceAdmission{roots:ManuallyDrop<Option<SourceRoots>>,issued:ManuallyDrop<Option<SealedShared<SourceRoots>>>}
impl OriginalCallerSourceAdmission{
 /// 🪹️ Creates only empty inline custody.
 pub fn new()->Self{Self{roots:ManuallyDrop::new(None),issued:ManuallyDrop::new(None)}}
 /// 🈳️ Checks both actual resident slots.
 pub fn terminal_is_empty(&self)->bool{self.roots.is_none()&&self.issued.is_none()}
 /// 👁️ Observes only the original resident root and backing slots.
 pub fn has_roots(&self)->bool{self.roots.is_some()}
 pub fn has_backing(&self)->bool{self.issued.is_some()}
 /// 🪪️ Observes the same original owners while assembled roots remain unpublished.
 pub fn payload_identity(&self)->Option<crate::OriginalPayloadSourceIdentity>{self.roots.as_ref().and_then(|roots|roots.authority.identity())}
 pub fn cancellation_identity(&self)->Option<crate::OriginalCancelRootIdentity>{self.roots.as_ref().map(|roots|crate::OriginalCancelRootAdmission::token_identity(&roots.cancel))}
 /// 📏️ Quotes the two actual input headers and assembled Source roots.
 pub fn prepare_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<JobPayloadAuthority>>()+size_of::<Option<CancelToken>>()+size_of::<Option<SourceRoots>>(),depth:1,..Default::default()}}
 /// 🏗️ Assembles only from the caller-owned live inputs after the original work receipt.
 pub fn prepare(&mut self,authority:&mut Option<JobPayloadAuthority>,cancel:&mut Option<CancelToken>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome{
  let before=effect.performed_boundary();let result=(||{if !self.terminal_is_empty(){return Err(refused("Source admission already retains an owner"))}let Some(original)=authority.as_ref()else{return Err(refused("Source admission lacks its original payload owner"))};if original.terminal_is_empty(){return Err(refused("Source admission payload owner is closed"))}if cancel.is_none(){return Err(refused("Source admission lacks its original cancellation owner"))}let demand=Self::prepare_demand();if effect.remaining_work_units()?<1||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return Ok(RetainedCloneStep::Progress(Default::default()))}if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source assembly exceeded its original work"))}let birth=ORIGINAL_RETURN_BIRTH.fetch_update(std::sync::atomic::Ordering::Relaxed,std::sync::atomic::Ordering::Relaxed,|value|value.checked_add(1)).map(u64::from).map_err(|_|refused("Source birth identity exhausted"))?;let turns=OriginalSourceTurnIssuer::new();let returns=OriginalReturnSource::empty(birth);let native=native::NativeSources::new();let clock=SourceClockOwner::new(semio_framework_job_clock::OriginalSourceClock::new());let authority=authority.take().expect("original payload slot checked");let cancel=cancel.take().expect("original cancellation slot checked");*self.roots=Some(SourceRoots{turns,authority,cancel,returns,native,clock});Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))})();RetainedWorkOutcome{result,work:effect.performed_since(before).expect("same Source assembly receipt")}
 }
 /// 📏️ Quotes the actual sealed backing allocation before its allocator attempt.
 pub fn backing_demand()->Result<RetirementDemand,ValueError>{SealedShared::<SourceRoots>::source_admission_demand()}
 /// ⛽️ Quotes the actual sealed backing work.
 pub fn backing_work_demand()->u64{SealedShared::<SourceRoots>::source_admission_work_demand()}
 /// 👶️ Attempts the actual sealed backing while the original roots stay resident on refusal.
 pub fn admit_backing(&mut self,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome{if self.issued.is_some()||self.roots.is_none(){return RetainedWorkOutcome{result:Err(refused("Source backing has no eligible original roots")),work:0}}SealedShared::admit_from(&mut self.roots,SourceRoots::issuer(),&mut self.issued,effect)}
 /// 📤️ Returns the exact original inputs from an unallocated Source root after paid admission.
 pub fn return_inputs(&mut self,authority:&mut Option<JobPayloadAuthority>,cancel:&mut Option<CancelToken>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome{let before=effect.performed_boundary();let result=(||{if self.issued.is_some(){return Err(refused("born Source must be published and retired"))}if authority.is_some()||cancel.is_some(){return Err(refused("Source return output is occupied"))}if self.roots.is_none(){return Ok(RetainedCloneStep::Complete(Default::default()))}let demand=Self::prepare_demand();if effect.remaining_work_units()?<1||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return Ok(RetainedCloneStep::Progress(Default::default()))}if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source input return exceeded its original work"))}let roots=self.roots.take().expect("original roots slot checked");let SourceRoots{authority:original_authority,cancel:original_cancel,..}=roots;*authority=Some(original_authority);*cancel=Some(original_cancel);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))})();RetainedWorkOutcome{result,work:effect.performed_since(before).expect("same Source input return receipt")}}
 /// 📏️ Quotes the actual issued backing and Source parent output headers.
 pub fn publish_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<SealedShared<SourceRoots>>>()+size_of::<Option<OriginalCallerSourceParent>>(),depth:1,..Default::default()}}
 /// 📤️ Publishes the same successfully born backing directly to its caller-owned parent slot.
 pub fn publish(&mut self,output:&mut Option<OriginalCallerSourceParent>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome{let before=effect.performed_boundary();let result=(||{if output.is_some(){return Err(refused("Source parent output is occupied"))}if self.roots.is_some(){return Err(refused("Source backing is not yet admitted"))}if self.issued.is_none(){return Ok(RetainedCloneStep::Progress(Default::default()))}let demand=Self::publish_demand();if effect.remaining_work_units()?<1||!semio_framework_value_retained_clone::retained_clone::retained_clone_grant_admits(effect.grant(),demand){return Ok(RetainedCloneStep::Progress(Default::default()))}if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source publication exceeded its original work"))}let original=self.issued.take();*output=Some(OriginalCallerSourceParent{original:ManuallyDrop::new(original),retiring:ManuallyDrop::new(None),pending_roots:ManuallyDrop::new(None),pending_owner:ManuallyDrop::new(None),borrowed_cancel:false,borrowed_source:false,lending_open:true,clock_authority:None});Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))})();RetainedWorkOutcome{result,work:effect.performed_since(before).expect("same Source publication receipt")}}
}
impl Default for OriginalCallerSourceAdmission{fn default()->Self{Self::new()}}
impl Drop for OriginalCallerSourceAdmission{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Source admission retains its original owners");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.roots);ManuallyDrop::drop(&mut self.issued)}}}}
